(7378568, 1157208, 65858, '<td valign="top">Lovely textures!</td>', 'Lovely textures!', '2015-07-01 01:11:55.000000', NULL, 1),
(7378572, 1158171, 62249, '<td valign="top">Excellent sharp focus on the bird, and lovely blurred background. The raindrops are great, too.</td>', 'Excellent sharp focus on the bird, and lovely blurred background. The raindrops are great, too.', '2015-07-01 01:14:23.000000', NULL, 1),
(7378574, 1158729, 62249, '<td valign="top">Nice colors and the simple boat is a great contrast with the complexity of the city.</td>', 'Nice colors and the simple boat is a great contrast with the complexity of the city.', '2015-07-01 01:15:03.000000', NULL, 1),
(7378575, 1158883, 65858, '<td valign="top">A stunning and honest portrait - very nice!</td>', 'A stunning and honest portrait - very nice!', '2015-07-01 01:15:39.000000', NULL, 1),
(7378577, 1157332, 62249, '<td valign="top">Hmmm. Seems that this same object was an entry in the puzzle macro.I like the repeated patterns.</td>', 'Hmmm. Seems that this same object was an entry in the puzzle macro.I like the repeated patterns.', '2015-07-01 01:15:55.000000', NULL, 1),
(7378578, 1158513, 65858, '<td valign="top">Wow, what a view! Beautiful!</td>', 'Wow, what a view! Beautiful!', '2015-07-01 01:15:55.000000', NULL, 1),
(7378579, 1158595, 62249, '<td valign="top">An outtake from puzzle macro? Maybe remove the bright spot in the capstan reflection.</td>', 'An outtake from puzzle macro? Maybe remove the bright spot in the capstan reflection.', '2015-07-01 01:16:44.000000', NULL, 1),
(7378580, 1158334, 65858, '<td valign="top">Wow, nice timing.</td>', 'Wow, nice timing.', '2015-07-01 01:16:46.000000', NULL, 1),
(7378581, 1158639, 65858, '<td valign="top">Really lovely sky! I wish the was just a touch more detail in the dark rocks, but it is a nice mood.</td>', 'Really lovely sky! I wish the was just a touch more detail in the dark rocks, but it is a nice mood.', '2015-07-01 01:17:22.000000', NULL, 1),
(7378584, 1158719, 62249, '<td valign="top">The background surface is lovely. Coffee cup needs some light bounced into it to separate the contents from the left edge of the cup.</td>', 'The background surface is lovely. Coffee cup needs some light bounced into it to separate the contents from the left edge of the cup.', '2015-07-01 01:17:38.000000', NULL, 1),
(7378586, 1158529, 65858, '<td valign="top">Pretty textures and colors. I don''t feel like there''s a definite focal point, but that''s just me.</td>', 'Pretty textures and colors. I don''t feel like there''s a definite focal point, but that''s just me.', '2015-07-01 01:18:05.000000', NULL, 1),
(7378588, 1158310, 65858, '<td valign="top">Really nice composition and stunning capture!</td>', 'Really nice composition and stunning capture!', '2015-07-01 01:18:24.000000', NULL, 1),
(7378589, 1157601, 62249, '<td valign="top">The green background kinda of smacks me in the eyeballs, but the lighting on the daisies is spot on.</td>', 'The green background kinda of smacks me in the eyeballs, but the lighting on the daisies is spot on.', '2015-07-01 01:18:29.000000', NULL, 1),
(7378592, 1157601, 65858, '<td valign="top">Ha, I like the double meaning you came up with! The colors look a tad hot / oversaturated, but maybe it''s my monitor.</td>', 'Ha, I like the double meaning you came up with! The colors look a tad hot / oversaturated, but maybe it''s my monitor.', '2015-07-01 01:19:31.000000', NULL, 1),
(7378595, 1158842, 62249, '<td valign="top">Given the overall desaturated look of the image, I find the blue object at the left edge kind of distracting.</td>', 'Given the overall desaturated look of the image, I find the blue object at the left edge kind of distracting.', '2015-07-01 01:19:44.000000', NULL, 1),
(7378598, 1157950, 62249, '<td valign="top">Boy, whenever I try stuff like this I practically get booed on DPC. I applaud your gumption for doing this for a tough crowd and am giving you a high score accordingly. Only criticism: remove the light spot just below the green arrow.</td>', 'Boy, whenever I try stuff like this I practically get booed on DPC. I applaud your gumption for doing this for a tough crowd and am giving you a high score accordingly. Only criticism: remove the light spot just below the green arrow.', '2015-07-01 01:21:33.000000', NULL, 1),
(7378599, 1158903, 65858, '<td valign="top">Really lovely color, thoughtful composition, and I love wide angles like this!</td>', 'Really lovely color, thoughtful composition, and I love wide angles like this!', '2015-07-01 01:21:39.000000', NULL, 1),
