(7379565, 1158362, 49480, '<td valign="top">Very cool shot.  The caption brings it together for me.</td>', 'Very cool shot.  The caption brings it together for me.', '2015-07-01 22:25:13.000000', NULL, 1),
(7379566, 1157540, 49480, '<td valign="top">I think I see where you were going with this but I don''t think it worked out.  Maybe a pulsed flash for holding the lines or a bulb exposure where the movements in between positions would be very short.  As is it''s too hard to pick out the dominant third lines.</td>', 'I think I see where you were going with this but I don''t think it worked out.  Maybe a pulsed flash for holding the lines or a bulb exposure where the movements in between positions would be very short.  As is it''s too hard to pick out the dominant third lines.', '2015-07-01 22:27:34.000000', NULL, 1),
(7379567, 1158386, 49480, '<td valign="top">At first I was bothered by nothing being in focus, but then it grew on me that the subject was the OOF glow of the lights which has an ethereal quality.  Very pretty!</td>', 'At first I was bothered by nothing being in focus, but then it grew on me that the subject was the OOF glow of the lights which has an ethereal quality.  Very pretty!', '2015-07-01 22:28:53.000000', NULL, 1),
(7379570, 1158783, 96751, '<td valign="top">Hehehe, great shot Mark. Hope you didn''t scratch up the roof of your car :)</td>', 'Hehehe, great shot Mark. Hope you didn''t scratch up the roof of your car :)', '2015-07-01 22:35:54.000000', NULL, 1),
