(7379691, 1158171, 113411, '<td valign="top">what an incredible shot!!!</td>', 'what an incredible shot!!!', '2015-07-02 00:27:44.000000', NULL, 1),
(7379782, 1158600, 180676, '<td valign="top">Very serene and captured well.  Is that a dust bunny on the mid left though?</td>', 'Very serene and captured well.  Is that a dust bunny on the mid left though?', '2015-07-02 03:11:59.000000', NULL, 1),
(7379783, 1157200, 180676, '<td valign="top">Nice composition!  Love the colors of MYA compared to the drab misted over boats in the distance.</td>', 'Nice composition!  Love the colors of MYA compared to the drab misted over boats in the distance.', '2015-07-02 03:12:48.000000', NULL, 1),
(7379784, 1158883, 180676, '<td valign="top">Stunning use of negative space to achieve this look, and the clarity of the eyes is quite nice!</td>', 'Stunning use of negative space to achieve this look, and the clarity of the eyes is quite nice!', '2015-07-02 03:13:18.000000', NULL, 1),
(7379785, 1158844, 180676, '<td valign="top">Way to tug at the heart strings!</td>', 'Way to tug at the heart strings!', '2015-07-02 03:13:56.000000', NULL, 1),
(7379791, 1158386, 114285, '<td valign="top">Love this one!! I get the feeling it was one of those days where you''ve had a hard day at the office, your''e dying to get home to a lovely warm cooked meal, but you still have a long way to go and your eyes are weary. Thankyou.</td>', 'Love this one!! I get the feeling it was one of those days where you''ve had a hard day at the office, your''e dying to get home to a lovely warm cooked meal, but you still have a long way to go and your eyes are weary. Thankyou.', '2015-07-02 03:26:36.000000', NULL, 1),
(7379794, 1158200, 114285, '<td valign="top">Now that is one cute bull, with a great set of horns. Lovely light in this one.</td>', 'Now that is one cute bull, with a great set of horns. Lovely light in this one.', '2015-07-02 03:27:57.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7379796, 1158835, 114285, '<td valign="top">Sharp, the eyes freak me OUT!!!</td>', 'Sharp, the eyes freak me OUT!!!', '2015-07-02 03:28:48.000000', NULL, 1),
(7379845, 1158849, 180618, '<td valign="top">too busy, what is the ROT in this? don''t get it.</td>', 'too busy, what is the ROT in this? don''t get it.', '2015-07-02 04:29:25.000000', NULL, 1),
(7380073, 1158732, 114225, '<td valign="top">There is magic in this photo.</td>', 'There is magic in this photo.', '2015-07-02 12:17:57.000000', NULL, 1),
(7380114, 1158874, 1792, '<td valign="top">Ithink you mean palms</td>', 'Ithink you mean palms', '2015-07-02 12:51:51.000000', NULL, 1),
(7380142, 1158272, 175880, '<td valign="top">Hahaha. super title</td>', 'Hahaha. super title', '2015-07-02 13:09:26.000000', NULL, 1),
(7380249, 1158639, 151548, '<td valign="top">I especially like the golden windows but a beautiful composition. Should ribbon.</td>', 'I especially like the golden windows but a beautiful composition. Should ribbon.', '2015-07-02 14:21:42.000000', NULL, 1),
(7380251, 1158541, 151548, '<td valign="top">So reminiscent for me. Lovely composition and lighting.</td>', 'So reminiscent for me. Lovely composition and lighting.', '2015-07-02 14:22:38.000000', NULL, 1),
(7380254, 1158490, 151548, '<td valign="top">Works well. Your model deserves congratulations.</td>', 'Works well. Your model deserves congratulations.', '2015-07-02 14:23:49.000000', NULL, 1),
(7380444, 1158272, 177030, '<td valign="top">Love your title and a great example of personification, not to mention "Rule of Thirds", "Leading Lines", "Sense of Scale", and probably other techniques.  Well done; a top pick from me.</td>', 'Love your title and a great example of personification, not to mention "Rule of Thirds", "Leading Lines", "Sense of Scale", and probably other techniques.  Well done; a top pick from me.', '2015-07-02 15:47:48.000000', NULL, 1),
(7380447, 1158707, 177030, '<td valign="top">Nothing but the essential elements.  Love the composition and sense of motion.</td>', 'Nothing but the essential elements.  Love the composition and sense of motion.', '2015-07-02 15:49:09.000000', NULL, 1),
(7380451, 1158715, 177030, '<td valign="top">Cannot get more "Rule of Thirds" than this.  Nice find (or set up).  Well shot.</td>', 'Cannot get more "Rule of Thirds" than this.  Nice find (or set up).  Well shot.', '2015-07-02 15:50:44.000000', NULL, 1),
(7380462, 1158049, 177030, '<td valign="top">Classic shot and use of the thirds rule.  There is a loss in detail I wish were there.  My guess is a lower resolution camera, extreme telephoto, heavily cropped or a bit of all three.  Still like the shot.</td>', 'Classic shot and use of the thirds rule.  There is a loss in detail I wish were there.  My guess is a lower resolution camera, extreme telephoto, heavily cropped or a bit of all three.  Still like the shot.', '2015-07-02 15:56:20.000000', NULL, 1),
(7380468, 1157129, 177030, '<td valign="top">Great perspective and the lighter colored hat in a sea of similar tones just makes the shot. Really well done.</td>', 'Great perspective and the lighter colored hat in a sea of similar tones just makes the shot. Really well done.', '2015-07-02 15:57:54.000000', NULL, 1),
(7380470, 1157520, 62249, '<td valign="top">Well exposed. I don''t think the texture particularly helps the image.</td>', 'Well exposed. I don''t think the texture particularly helps the image.', '2015-07-02 15:58:29.000000', NULL, 1),
(7380473, 1157287, 62249, '<td valign="top">Good title. Cute capture. Perhaps you could''ve removed the white spot below the stick blade?</td>', 'Good title. Cute capture. Perhaps you could''ve removed the white spot below the stick blade?', '2015-07-02 15:59:48.000000', NULL, 1),
(7380476, 1158136, 62249, '<td valign="top">Nice sharp focus. Any reason you didn''t remove the splotch in the sky to the right of the tower?</td>', 'Nice sharp focus. Any reason you didn''t remove the splotch in the sky to the right of the tower?', '2015-07-02 16:01:37.000000', NULL, 1),
(7380477, 1158362, 62249, '<td valign="top">Gorgeous. A great dreamy feeling and nicely processed.</td>', 'Gorgeous. A great dreamy feeling and nicely processed.', '2015-07-02 16:02:11.000000', NULL, 1),
(7380479, 1158513, 62249, '<td valign="top">Sharp focus. Good tonal range. Meets the challenge. Isn''t an especially interesting composition.</td>', 'Sharp focus. Good tonal range. Meets the challenge. Isn''t an especially interesting composition.', '2015-07-02 16:03:47.000000', NULL, 1),
(7380481, 1158418, 177030, '<td valign="top">I suspect you will get comments about not strictly meeting the rule of thirds. What I like: separation of subject with the black background, hint of back-lighting, sharpness, clarity, and overall processing.  What I wish were better, composition to move the main focal point, the flower, to a thirds point.</td>', 'I suspect you will get comments about not strictly meeting the rule of thirds. What I like: separation of subject with the black background, hint of back-lighting, sharpness, clarity, and overall processing.  What I wish were better, composition to move the main focal point, the flower, to a thirds point.', '2015-07-02 16:05:21.000000', NULL, 1),
(7380482, 1158679, 62249, '<td valign="top">Love the field of flowers. Nice clouds too. A bit of halo-ing along the tops of the trees.</td>', 'Love the field of flowers. Nice clouds too. A bit of halo-ing along the tops of the trees.', '2015-07-02 16:06:28.000000', NULL, 1),
(7380483, 1158200, 177030, '<td valign="top">Super lighting and post processing to bring it out.</td>', 'Super lighting and post processing to bring it out.', '2015-07-02 16:08:29.000000', NULL, 1),
(7380484, 1157503, 62249, '<td valign="top">Nice lighting. Good sharpness &amp; DOF. The strong horizontal banding in the background (I''m guessing it''s fence rails) really detracts from the image.</td>', 'Nice lighting. Good sharpness & DOF. The strong horizontal banding in the background (I''m guessing it''s fence rails) really detracts from the image.', '2015-07-02 16:09:13.000000', NULL, 1),
(7380485, 1158190, 62249, '<td valign="top">The model is interesting. The background sign is distracting. Processing seems too contrasty for the subject matter.</td>', 'The model is interesting. The background sign is distracting. Processing seems too contrasty for the subject matter.', '2015-07-02 16:12:07.000000', NULL, 1),
(7380486, 1158843, 177030, '<td valign="top">I think changing perspective to move the fore ground objects to a thirds point rather than only the water line might have been better for this challenge.  Still a good shot.</td>', 'I think changing perspective to move the fore ground objects to a thirds point rather than only the water line might have been better for this challenge.  Still a good shot.', '2015-07-02 16:12:08.000000', NULL, 1),
