(7380495, 1158908, 177030, '<td valign="top">Appears underexposed on my monitor by about 1/2 stop.  A greater range of tones would make this really pop.</td>', 'Appears underexposed on my monitor by about 1/2 stop.  A greater range of tones would make this really pop.', '2015-07-02 16:21:57.000000', NULL, 1),
